require "yaml"
def leaves(h, p = [], out = {})
  h.each { |k, v| v.is_a?(Hash) ? leaves(v, p + [k.to_s], out) : out[(p + [k.to_s]).join(".")] = v }
  out
end
head = {}
Dir["/tmp/head_en/config/locales/en/*.yml"].each { |f| head.merge!(leaves(YAML.load_file(f)["en"] ? {"en" => YAML.load_file(f)["en"]} : {})) }
cur = {}
Dir["/app/config/locales/en/*.yml"].each { |f| cur.merge!(leaves(YAML.load_file(f))) }
removed = head.keys - cur.keys
added = cur.keys - head.keys
changed = (head.keys & cur.keys).reject { |k| head[k] == cur[k] }
puts "removed=#{removed.size} added=#{added.size} changed=#{changed.size}"
puts "ADDED: #{added.first(10)}" unless added.empty?
puts "CHANGED: #{changed.first(10)}" unless changed.empty?
File.write("/tmp/removed_en_keys.txt", removed.sort.join("\n") + "\n")
RUBY
